{
  "critique": [
    {
      "design": "r1A",
      "good": "Flight identifiers and time values remain intact. Destination names wrap at spaces, and the two time columns have a consistent rhythm.",
      "problems": "The initial viewport cuts through the Estimated header and leaves Gate and Status offscreen. Several destination rows are tall, while Paris occupies three lines.",
      "cause": "The first three columns use 286px, so the 98px Estimated column extends beyond the 360px viewport. The 110px Destination column is still too narrow to keep longer names on one line."
    },
    {
      "design": "r1B",
      "good": "The narrower Destination and Estimated columns save 11px without introducing word splits or increasing row heights. The paired times remain easy to compare.",
      "problems": "The Estimated header still meets the viewport edge, and Gate and Status require horizontal scrolling. Destination wrapping produces the same tall rows as r1A.",
      "cause": "The 103px Destination column remains wide enough for its longest word but not for several complete names. At 94px, Estimated fits its header in the table, though its right edge falls outside the viewport."
    },
    {
      "design": "r1C",
      "good": "The identifying columns and paired times retain the same readable layout as r1B. The wider Status column gives its contents more room.",
      "problems": "The extra status width increases scrolling without improving the visible portion or reducing the reported row heights. Gate and Status remain offscreen initially.",
      "cause": "Status grows from 89px to 100px, but it is already beyond the viewport and destination wrapping determines the taller rows."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "compact-intact",
      "widths": [78, 103, 98, 94, 55, 89],
      "change": "Use r1B as the compact intact baseline: it preserves headers and unbreakable content while keeping horizontal scrolling to the smallest of the three designs."
    },
    {
      "name": "roomier-destinations",
      "widths": [78, 140, 98, 94, 55, 89],
      "change": "Give destinations more room to reduce wrapping where possible. This makes rows easier to scan at the cost of more horizontal scrolling and less of Estimated in the initial viewport."
    },
    {
      "name": "more-first-screen",
      "widths": [78, 103, 80, 78, 55, 89],
      "change": "Narrow the time columns to bring the start of Gate into the initial viewport. This tests whether showing more of the operational columns is worth splitting the Scheduled and Estimated headers."
    }
  ]
}
